namespace sv_d62c915ee8244e0cbce65533eda5a424.Services;

/// <summary>
/// Scoped service (per-circuit) that provides low-stock alert counts
/// and coordinates polling with cross-component notification.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private CancellationTokenSource? _pollCts;
    private int _activeSubscribers;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChangedAsync;
    }

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Starts 10-second polling. Reference-counted so multiple callers
    /// share a single polling loop.
    /// </summary>
    public async Task StartPollingAsync()
    {
        _activeSubscribers++;
        if (_activeSubscribers == 1)
        {
            _pollCts = new CancellationTokenSource();
            _ = PollLoopAsync(_pollCts.Token);
        }

        // Fetch immediately so the caller gets data right away.
        await RefreshAsync();
    }

    public void StopPolling()
    {
        _activeSubscribers = Math.Max(0, _activeSubscribers - 1);
        if (_activeSubscribers == 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped.
        }
    }

    private async Task RefreshAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouse.Id);

        if (OnAlertDataChanged is not null)
            await OnAlertDataChanged.Invoke();
    }

    private async Task HandleWarehouseChangedAsync()
    {
        if (_activeSubscribers > 0)
            await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChangedAsync;
        _pollCts?.Cancel();
        _pollCts?.Dispose();
    }
}

