@using sv_d62c915ee8244e0cbce65533eda5a424.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" style="width: 220px;"
        value="@WarehouseState.CurrentWarehouse.Id"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseState.Warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChangedAsync;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
            await WarehouseState.SetWarehouseAsync(id);
    }

    private async Task StateHasChangedAsync()
    {
        await InvokeAsync(StateHasChanged);
        return;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChangedAsync;
    }
}

