@page "/dashboard"
@using sv_d62c915ee8244e0cbce65533eda5a424.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouse.Name</h5>
        <p class="card-text">
            Low-stock items:
            <span class="badge fs-6 @(AlertService.CurrentLowStockCount > 0 ? "bg-danger" : "bg-success")">
                @AlertService.CurrentLowStockCount
            </span>
        </p>
        <p class="text-muted small mb-0">
            Polling every 10 seconds. Last refresh: @_lastRefresh.ToString("HH:mm:ss")
        </p>
    </div>
</div>

@code {
    private DateTime _lastRefresh = DateTime.Now;

    protected override async Task OnInitializedAsync()
    {
        AlertService.OnAlertDataChanged += OnDataChanged;
        WarehouseState.OnChange += OnDataChanged;
        await AlertService.StartPollingAsync();
    }

    private async Task OnDataChanged()
    {
        _lastRefresh = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= OnDataChanged;
        WarehouseState.OnChange -= OnDataChanged;
        AlertService.StopPolling();
    }
}

